using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Reflection;using System.Diagnostics;
class Check {
 [STAThread] static void Main(string[] args){try{Run(args);}catch(Exception e){File.WriteAllText("integration-failure.txt",e.GetType().FullName+" / "+e.Message+" / "+(e.InnerException==null?"none":e.InnerException.GetType().FullName+" "+e.InnerException.Message));Environment.ExitCode=1;}}
 static void Run(string[] args){Application.EnableVisualStyles();var assembly=Assembly.LoadFrom(Path.GetFullPath(args[0]));var type=assembly.GetType("Suite+StartupAnimation",true);var flags=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;
 Func<Form> make=()=> (Form)Activator.CreateInstance(type,true);
 if(args.Length>1&&args[1]=="hold"){using(var view=make()){var hold=new Timer{Interval=20};hold.Tick+=(s,e)=>{var clock=(Stopwatch)type.GetField("clock",flags).GetValue(view);if(clock.Elapsed.TotalSeconds>3.6)clock.Stop();};view.Shown+=(s,e)=>hold.Start();view.ShowDialog();hold.Dispose();File.WriteAllText("ui-close.txt","closed");}return;}
 using(var view=make()){foreach(int width in new[]{660,1100,1375}){view.ClientSize=new Size(width,width*700/1100);foreach(double time in new[]{.6,1.5,2.7,3.8,5.7,6.9}){using(var bmp=new Bitmap(view.Width,view.Height))using(var g=Graphics.FromImage(bmp)){type.GetMethod("RenderFrame",flags).Invoke(view,new object[]{g,time});bmp.Save("frame-"+width+"-"+time.ToString("0.0",System.Globalization.CultureInfo.InvariantCulture)+".png");}}}}
 using(var view=make()){var watch=Stopwatch.StartNew();view.ShowDialog();if(watch.Elapsed.TotalSeconds<7||watch.Elapsed.TotalSeconds>10)throw new Exception("Natural playback duration incorrect");}
 using(var view=make()){var watch=Stopwatch.StartNew();var key=new Timer{Interval=140};view.Shown+=(s,e)=>key.Start();key.Tick+=(s,e)=>{key.Stop();var message=new Message();var arguments=new object[]{message,Keys.Escape};if(!(bool)type.GetMethod("ProcessCmdKey",flags).Invoke(view,arguments))throw new Exception("Escape not handled");};view.ShowDialog();key.Dispose();if(watch.Elapsed.TotalSeconds>1)throw new Exception("Escape did not skip promptly");}
 using(var view=make()){var click=new Timer{Interval=140};view.Shown+=(s,e)=>click.Start();click.Tick+=(s,e)=>{click.Stop();((Button)type.GetField("skip",flags).GetValue(view)).PerformClick();};view.ShowDialog();click.Dispose();}
 var suite=assembly.GetType("Suite");suite.GetField("root",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,Path.GetFullPath(Path.GetDirectoryName(args[0])));suite.GetMethod("BuildLauncherForm",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);var launcher=(Form)suite.GetField("form",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);using(var bitmap=new Bitmap(launcher.Width,launcher.Height))launcher.DrawToBitmap(bitmap,new Rectangle(0,0,bitmap.Width,bitmap.Height));launcher.Dispose();
 File.WriteAllText("validation.json","{\"ok\":true,\"renderedFrames\":18,\"naturalCompletion\":true,\"escapeHandled\":true,\"skipButtonHandled\":true}");Console.WriteLine("PASS 18 scaled frames, natural completion, Esc and skip button");
 }
}
